SELECT p.gender, a.admittime, d.diagnosis_code, COUNT(*) AS event_count, CAST(COUNT(*) filter (WHERE d.diagnosis_code = '757070') AS FLOAT) / NULLIF(COUNT(*), 0) AS proportion_of_chest_pain, AVG(e.value) AS average_value, MEDIAN(e.value) AS median_value, (percentile_cont(0.75) within GROUP (ORDER BY e.value) - percentile_cont(0.25) within GROUP (ORDER BY e.value)) AS interquartile_range FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents e ON a.hadm_id = e.hadm_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2017 AND 2018 AND d.diagnosis_code = '757070' GROUP BY p.gender, a.admittime, d.diagnosis_code ORDER BY p.gender, a.admittime, d.diagnosis_code NULLS LAST;